const fleet = [
  {id:'dzire',name:'Maruti Suzuki Dzire',category:'Sedan',tag:'CITY DAYS. EASY GETAWAYS.',seats:5,image:'',alt:'Maruti Suzuki Dzire'},
  {id:'baleno',name:'Maruti Suzuki Baleno',category:'Hatchback',tag:'MORE ROOM FOR YOUR PLANS',seats:5,image:'',alt:'Maruti Suzuki Baleno'},
  {id:'i20',name:'Hyundai i20',category:'Hatchback',tag:'MAKE EVERY DAY A DRIVE',seats:5,image:'',alt:'Hyundai i20'}
];
let mode='self', category='All';
const $=id=>document.getElementById(id);
const money=n=>'₹'+n.toLocaleString('en-IN');
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const today=new Date(), tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);
$('start-date').min=localDate(today);$('start-date').value=localDate(today);$('end-date').min=localDate(tomorrow);$('end-date').value=localDate(tomorrow);$('year').textContent=today.getFullYear();
function validDates(){const start=$('start-date').value,end=$('end-date').value;if(!start||!end||start<localDate(new Date())||end<=start){$('search-error').textContent='Choose a pick-up date from today and a return date after pick-up.';return false;}$('search-error').textContent='';return true;}
function render(){const list=fleet.filter(c=>category==='All'||c.category===category);$('result-count').textContent=`${list.length} ${list.length===1?'car':'cars'} · ${$('city').value} · ${mode==='self'?'Self-drive':'With a chauffeur'}`;$('cars').innerHTML=list.map(c=>`<article class="car-card"><div class="car-image"><img src="${c.image}" alt="${c.alt}" loading="lazy"><span class="car-tag">${c.tag}</span></div><div class="car-body"><div class="car-title"><h3>${c.name}</h3><span>${c.category}</span></div><div class="car-specs"><span>♙ ${c.seats} seats</span><span>◈ ${c.category}</span></div><div class="car-bottom"><div class="price">Request a quote</div><button class="ride-button" data-book="${c.id}">View ride</button></div></div></article>`).join('');}
document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;document.querySelectorAll('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));
$('city').addEventListener('change',render);
$('start-date').addEventListener('change',()=>{const d=new Date($('start-date').value+'T12:00:00');if(Number.isNaN(d.getTime()))return;d.setDate(d.getDate()+1);$('end-date').min=localDate(d);if($('end-date').value<localDate(d))$('end-date').value=localDate(d);});
$('search-form').addEventListener('submit',e=>{e.preventDefault();if(validDates()){render();$('fleet').scrollIntoView({behavior:'smooth'});}});
document.querySelectorAll('.city-card').forEach(b=>b.addEventListener('click',()=>{$('city').value=b.dataset.city;render();$('search').scrollIntoView({behavior:'smooth'});}));
function openTrip(id){if(!validDates()){$('search').scrollIntoView({behavior:'smooth'});return;}const car=fleet.find(c=>c.id===id);if(!car)return;const days=Math.round((Date.parse($('end-date').value)-Date.parse($('start-date').value))/86400000);const fmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});$('booking-content').innerHTML=`<div class="dialog-eyebrow">YOUR TRIP, AT A GLANCE</div><h2>${car.name}</h2><p style="color:var(--muted);font-size:14px">${mode==='self'?'Self-drive. Your own pace.':'With a chauffeur. Enjoy the journey.'}</p><div class="trip-summary"><div class="trip-row"><span>Pick-up city</span><strong>${$('city').value}</strong></div><div class="trip-row"><span>Pick-up</span><strong>${fmt($('start-date').value)}</strong></div><div class="trip-row"><span>Return</span><strong>${fmt($('end-date').value)}</strong></div><div class="trip-row"><span>Duration</span><strong>${days} ${days===1?'day':'days'}</strong></div><div class="trip-row"><span>Rental price</span><strong>Request a quote</strong></div></div><p class="dialog-note"><strong>This is a booking preview.</strong> No car is reserved and no payment is taken. Ask GoRide for availability, your rental quote, deposits and inclusions before confirming your trip.</p><a class="primary" id="quote-link" target="_blank" rel="noopener noreferrer">Request quote on WhatsApp</a><button class="ride-button" id="done-preview" style="width:100%;margin-top:12px">Close preview</button>`;const message=`Hi GoRide, I would like a quote for ${car.name} in ${$('city').value}, ${mode==='self'?'self-drive':'with a chauffeur'}, from ${fmt($('start-date').value)} to ${fmt($('end-date').value)} (${days} ${days===1?'day':'days'}). Please confirm availability, price, deposit and inclusions.`;$('quote-link').href='https://wa.me/919100852287?text='+encodeURIComponent(message);$('booking-dialog').showModal();$('done-preview').onclick=()=> $('booking-dialog').close();}
$('cars').addEventListener('click',e=>{const b=e.target.closest('[data-book]');if(b)openTrip(b.dataset.book);});$('close-dialog').onclick=()=> $('booking-dialog').close();$('booking-dialog').addEventListener('click',e=>{if(e.target===$('booking-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
fetch('assets/images.json').then(r=>{if(!r.ok)throw Error('Images unavailable');return r.json();}).then(images=>{fleet.forEach(c=>{c.image=images[c.id].url;});$('hero-image').style.backgroundImage=`url("${images.hero.url}")`;render();}).catch(()=>{render();});
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  try{Promise.resolve(document.modelContext.registerTool({
    name:'configure_car_search',title:'Configure car search',
    description:'Set the visible GoRide city, rental mode and category filters. Fleet browsing only; does not reserve a car.',
    inputSchema:{type:'object',properties:{city:{type:'string',enum:['Bangalore','Chennai','Tirupati']},mode:{type:'string',enum:['self','driver']},category:{type:'string',enum:['All','Hatchback','Sedan']}},required:['city','mode','category'],additionalProperties:false},
    annotations:{readOnlyHint:false,untrustedContentHint:false},
    execute(input){if(!input||!['Bangalore','Chennai','Tirupati'].includes(input.city)||!['self','driver'].includes(input.mode)||!['All','Hatchback','Sedan'].includes(input.category))throw Error('Invalid search filters');$('city').value=input.city;document.querySelector(`[data-mode="${input.mode}"]`).click();document.querySelector(`[data-category="${input.category}"]`).click();return {city:$('city').value,mode,category,resultCount:fleet.filter(c=>category==='All'||c.category===category).length,reservationCreated:false};}
  },{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
